solution.solution.cpp:
#include <cstdint>
#include <string>
#include <vector>

struct Record { int client; std::uint32_t pid; std::uint8_t level; std::string text; };

class LogCollector
{
public:
    int connect(std::uint32_t pid)
    {
        clients.push_back({ pid, {}, true });
        return static_cast<int>(clients.size()) - 1;
    }

    void received(int client, const std::vector<std::uint8_t>& bytes)
    {
        if (!isConnected(client)) return;
        Client& c{ clients[client] };
        c.buffer.insert(c.buffer.end(), bytes.begin(), bytes.end());
        while (c.buffer.size() >= 2)
        {
            const std::size_t length{ static_cast<std::size_t>(c.buffer[0] | (c.buffer[1] << 8)) };
            if (length == 0 || length > 1025 || (c.buffer.size() >= 3 && c.buffer[2] > 5)) { fail(c); return; }
            if (c.buffer.size() < 2 + length) return;
            records.push_back({ client, c.pid, c.buffer[2], std::string(c.buffer.begin() + 3, c.buffer.begin() + 2 + static_cast<std::ptrdiff_t>(length)) });
            c.buffer.erase(c.buffer.begin(), c.buffer.begin() + 2 + static_cast<std::ptrdiff_t>(length));
        }
    }

    void disconnected(int client)
    {
        if (!isConnected(client)) return;
        Client& c{ clients[client] };
        if (!c.buffer.empty()) ++partials;
        c.buffer.clear();
        c.connected = false;
    }

    std::vector<Record> drain(std::uint8_t minLevel)
    {
        std::vector<Record> out;
        for (Record& r : records) if (r.level >= minLevel) out.push_back(std::move(r));
        records.clear();
        return out;
    }

    bool isConnected(int client) const { return client >= 0 && client < static_cast<int>(clients.size()) && clients[client].connected; }
    int partialDropped() const { return partials; }
    int protocolErrors() const { return errors; }

private:
    struct Client { std::uint32_t pid; std::vector<std::uint8_t> buffer; bool connected; };
    std::vector<Client> clients;
    std::vector<Record> records;
    int partials{ 0 }, errors{ 0 };

    void fail(Client& c) { ++errors; c.buffer.clear(); c.connected = false; }
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
static Bytes rec(std::uint8_t level, const std::string& text)
{
    const std::size_t n{ text.size() + 1 };
    Bytes b{ static_cast<std::uint8_t>(n), static_cast<std::uint8_t>(n >> 8), level };
    b.insert(b.end(), text.begin(), text.end());
    return b;
}
static Bytes join(std::initializer_list<Bytes> parts) { Bytes out; for (const Bytes& p : parts) out.insert(out.end(), p.begin(), p.end()); return out; }

TEST("records from one client, in pieces") {
    LogCollector log;
    const int a{ log.connect(4120) };
    const Bytes stream{ join({ rec(2, "starting"), rec(4, "disk full"), rec(1, "tick") }) };
    for (std::size_t i{ 0 }; i < stream.size(); i += 5)
        log.received(a, Bytes(stream.begin() + static_cast<std::ptrdiff_t>(i), stream.begin() + static_cast<std::ptrdiff_t>(std::min(i + 5, stream.size()))));
    const auto all{ log.drain(0) };
    CHECK_EQ(all.size(), 3u);
    if (all.size() == 3) { CHECK_EQ(all[1].text, std::string("disk full")); CHECK_EQ(all[1].level, 4); CHECK_EQ(all[1].pid, 4120u); }
    CHECK(log.drain(0).empty());
}
TEST("two clients, in completion order") {
    LogCollector log;
    const int a{ log.connect(10) }, b{ log.connect(20) };
    const Bytes ra{ rec(3, "from a") }, rb{ rec(3, "from b") };
    log.received(a, Bytes(ra.begin(), ra.begin() + 4));
    log.received(b, rb);
    log.received(a, Bytes(ra.begin() + 4, ra.end()));
    const auto all{ log.drain(0) };
    CHECK_EQ(all.size(), 2u);
    if (all.size() == 2) { CHECK_EQ(all[0].client, b); CHECK_EQ(all[1].client, a); }
}
TEST("filtering by level") {
    LogCollector log;
    const int a{ log.connect(1) };
    log.received(a, join({ rec(0, "trace"), rec(3, "warn"), rec(5, "fatal"), rec(2, "info") }));
    const auto important{ log.drain(3) };
    CHECK_EQ(important.size(), 2u);
    if (important.size() == 2) { CHECK_EQ(important[0].text, std::string("warn")); CHECK_EQ(important[1].text, std::string("fatal")); }
    CHECK(log.drain(0).empty());
}
TEST("bad records disconnect only that client") {
    LogCollector log;
    const int good{ log.connect(1) }, bad{ log.connect(2) };
    log.received(bad, join({ rec(2, "fine"), Bytes{ 0x00, 0x10, 1 } }));
    CHECK(!log.isConnected(bad));
    CHECK_EQ(log.protocolErrors(), 1);
    log.received(bad, rec(2, "ignored"));
    log.received(good, rec(2, "still here"));
    const auto all{ log.drain(0) };
    CHECK_EQ(all.size(), 2u);
    LogCollector levels;
    const int c{ levels.connect(3) };
    levels.received(c, rec(9, "bad level"));
    CHECK(!levels.isConnected(c));
    LogCollector zero;
    const int z{ zero.connect(4) };
    zero.received(z, Bytes{ 0, 0 });
    CHECK_EQ(zero.protocolErrors(), 1);
}
TEST("partial records at disconnect") {
    LogCollector log;
    const int a{ log.connect(1) }, b{ log.connect(2) };
    const Bytes r{ rec(2, "half") };
    log.received(a, Bytes(r.begin(), r.begin() + 3));
    log.disconnected(a);
    log.received(b, r);
    log.disconnected(b);
    CHECK_EQ(log.partialDropped(), 1);
    CHECK_EQ(log.drain(0).size(), 1u);
    CHECK(!log.isConnected(a));
}

